import sys
def parse(line):
    out, cur, q, i = [], "", False, 0
    while i < len(line):
        ch = line[i]
        if ch == '"':
            if q and i + 1 < len(line) and line[i + 1] == '"':
                cur += '"'; i += 1
            else:
                q = not q
        elif ch == "," and not q:
            out.append(cur); cur = ""
        else:
            cur += ch
        i += 1
    out.append(cur)
    return out
lines = sys.stdin.read().strip().split("\n")
head = parse(lines[0])
idx = head.index("name")
for l in lines[1:]:
    print(parse(l)[idx])

